 @Procedure(name="deposit.set.membership",mode=Mode.WRITE) public Stream<RelRow> membership(@Name("request") Map<String,Object> request,@Name("context") Map<String,Object> context) {return invoke(context,c->{var o=new DomainService(c).membership(request);return Stream.of(new RelRow(o.rel(),o.data(),c.meta()));});}
